    'faq_note' => 'Answers to common questions.',
    'faq_q1' => '<strong>What is TropaTT?</strong><br>A free openen-source self-hosted CRM, taak manager, and project management platform.',
    'faq_q10' => 'Who is the developer?',
    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM or a taak manager?</strong><br>Both. A CRM for clients and counterparties, a taak manager for taken, plus project management, chat, agenda, and AI.',
    'faq_q3' => '<strong>Is it suitable for freelancers?</strong><br>Yes. There is no minimum team size. A single gebruiker gets CRM, taken, an AI day plan, and chat without per-seat fees.',
    'faq_q4' => '<strong>Does it work on shared hosting?</strong><br>Yes. PHP 8.1+ and MySQL are enough. The browser installer configures everything.',
    'faq_q5' => '<strong>Are there limits on gebruikers and taken?</strong><br>No. Unlimited gebruikers, taken, projecten, and clients. The only limitation is server capacity.',
    'faq_q6' => '<strong>Where is the gegevens stored?</strong><br>100% on your server. The system never syncs gegevens to the cloud.',
    'faq_q7' => '<strong>What AI tools are beschikbaar?</strong><br>20+ tools: idea exploration, day/week plans, summaries, checklists, risks, meeting preparation.',
    'faq_q8' => '<strong>Is there an API?</strong><br>Yes, a REST API with an OpenAPI 3.1 spec generated from code.',
    'faq_q9' => '<strong>Can it be customized?</strong><br>Yes. PHP code, modules, webhooks, API, workflow rules, custom fields, rollen, and access rights.',
    'faq_title' => 'Frequently asked questions',
    'gantt_intro' => 'Gantt displays project taken on a timeline. It lets you plan deadlines, track dependencies, and monitor resource overload.',
    'gantt_item1' => 'Each taak is displayed as a bar on the timeline.',
    'gantt_item2' => 'Dependencies: taak B depends on taak A — shown on Gantt as a link.',
    'gantt_item3' => 'Critical path: the sequence of taken that determines the minimum project duration.',
