    'mcp_why' => '<strong>Why:</strong> MCP allows AI agents to read and manage your taken, projecten, clients, and chats through a unified protocol — with the same access toestemmingen as the web UI.',
    'mcp_intro' => 'TropaTT includes a built-in MCP (Model Context Protocol) server — the same protocol understood by Claude Code, Codex, ChatGPT, and other compatible AI agents.',
